Folgedes ist eine mögliche Lösung mit Laufzeit O(n):

def count_nodes(root):
    if not root:
        return 0
    return 1 + count_nodes(root.left) + count_nodes(root.right)

Es wird rekursiv der linke und der rechte Zweig abgearbeitet und dabei cout_nodes hochgezählt

```python
class MinStack:
    def __init__(self):
        # Initialize the main stack and an auxiliary stack to keep track of minimum values
        self.stack = []
        self.min_stack = []

    def push(self, x):
        """Push the element x onto the main stack."""
        self.stack.append(x)
        # Push the element onto the min stack if it is smaller than or equal to the current minimum
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)

    def pop(self):
        """Remove the top element from the main stack."""
        if self.stack:
            x = self.stack.pop()
            # If the popped element is the current minimum, pop it from the min stack as well
            if x == self.min_stack[-1]:
                self.min_stack.pop()
            return x
        return None

    def top(self):
        """Return the top element of the main stack without removing it."""
        if self.stack:
            return self.stack[-1]
        return None

    def isEmpty(self):
        """Return whether the main stack is empty."""
        return len(self.stack) == 0

    def getMin(self):
        """Return the minimum element in the main stack."""
        if self.min_stack:
            return self.min_stack[-1]
        return None
